-- Module 21: lightweight employees and immutable attendance events.
update public.module_definitions set configuration_schema='{"properties":{"employee_number_prefix":{"type":"string","label":"Employee number prefix","minLength":1,"maxLength":12,"default":"EMP"}},"additionalProperties":false}'::jsonb,updated_at=now()where key='employees';
update public.module_definitions set configuration_schema='{"properties":{"shift_start":{"type":"string","label":"Default shift start (24-hour time)","minLength":5,"maxLength":5,"default":"09:00"},"grace_period_minutes":{"type":"integer","label":"Late grace period (minutes)","minimum":0,"maximum":180,"default":0},"standard_day_minutes":{"type":"integer","label":"Standard workday (minutes)","minimum":60,"maximum":1440,"default":480},"capture_location":{"type":"boolean","label":"Allow optional location capture","default":false}},"additionalProperties":false}'::jsonb,updated_at=now()where key='attendance';

insert into public.permissions(key,domain,action,description)values
 ('employee.read','employee','read','View employee records'),('employee.manage','employee','manage','Create and manage employees'),
 ('attendance.read','attendance','read','View attendance and timesheets'),('attendance.manage','attendance','manage','Manage attendance records'),('attendance.clock','attendance','clock','Record attendance events')
on conflict(key)do update set domain=excluded.domain,action=excluded.action,description=excluded.description;

create function private.install_employee_attendance_permissions(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$begin
 insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager')and(permission.key like'employee.%'or permission.key like'attendance.%')on conflict do nothing;
 insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role join public.permissions permission on permission.key=any(case role.key when'staff'then array['employee.read','attendance.read','attendance.clock']when'viewer'then array['employee.read','attendance.read']else array[]::text[]end)where role.organization_id=requested_organization_id and role.key in('staff','viewer')on conflict do nothing;
end;$$;
create function private.handle_main_branch_employee_attendance_permissions()returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main'then perform private.install_employee_attendance_permissions(new.organization_id);end if;return new;end;$$;
create trigger zzzzzzzz_install_employee_attendance_permissions_on_main_branch after insert on public.branches for each row execute function private.handle_main_branch_employee_attendance_permissions();
select private.install_employee_attendance_permissions(id)from public.organizations;

create table public.employee_counters(organization_id uuid primary key references public.organizations(id)on delete cascade,next_value bigint not null default 1 check(next_value>0));
create table public.employees(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,branch_id uuid not null,employee_number text not null,
 name text not null check(char_length(btrim(name))between 1 and 160),contact text not null default''check(char_length(contact)<=500),position text not null check(char_length(btrim(position))between 1 and 120),
 employment_status text not null default'active'check(employment_status in('active','on_leave','inactive','terminated')),hire_date date not null,membership_id uuid,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(id,organization_id),unique(organization_id,employee_number),foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict,foreign key(membership_id,organization_id)references public.organization_memberships(id,organization_id)on delete restrict
);
create table public.employee_audit_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null,employee_id uuid not null,event text not null,actor_id uuid not null references auth.users(id),details jsonb not null default'{}',created_at timestamptz not null default now(),foreign key(employee_id,organization_id)references public.employees(id,organization_id)on delete cascade);
create table public.attendance_sessions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,employee_id uuid not null,branch_id uuid not null,work_date date not null,
 clock_in_at timestamptz not null,clock_out_at timestamptz,status text not null default'open'check(status in('open','closed')),is_late boolean not null default false,
 break_minutes integer not null default 0 check(break_minutes>=0),worked_minutes integer check(worked_minutes>=0),regular_minutes integer check(regular_minutes>=0),overtime_minutes integer check(overtime_minutes>=0),
 payroll_status text not null default'unprocessed'check(payroll_status in('unprocessed','ready','exported')),payroll_reference text,exported_at timestamptz,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),
 foreign key(employee_id,organization_id)references public.employees(id,organization_id)on delete restrict,foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict,
 check((status='open'and clock_out_at is null and worked_minutes is null and regular_minutes is null and overtime_minutes is null)or(status='closed'and clock_out_at is not null and worked_minutes is not null and regular_minutes is not null and overtime_minutes is not null)),check(clock_out_at is null or clock_out_at>=clock_in_at)
);
create table public.attendance_events(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,session_id uuid not null,employee_id uuid not null,branch_id uuid not null,event_type text not null check(event_type in('clock_in','break_start','break_end','clock_out')),
 occurred_at timestamptz not null,device_info jsonb not null default'{}'check(jsonb_typeof(device_info)='object'),latitude numeric(9,6),longitude numeric(9,6),idempotency_key text not null check(char_length(idempotency_key)between 1 and 200),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(organization_id,idempotency_key),foreign key(session_id,organization_id)references public.attendance_sessions(id,organization_id)on delete restrict,foreign key(employee_id,organization_id)references public.employees(id,organization_id)on delete restrict,foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict,
 check((latitude is null)=(longitude is null)),check(latitude is null or latitude between -90 and 90),check(longitude is null or longitude between -180 and 180)
);
create index employees_branch_status_idx on public.employees(organization_id,branch_id,employment_status,name);create index employee_audit_idx on public.employee_audit_history(employee_id,created_at desc);
create unique index attendance_one_open_session_idx on public.attendance_sessions(organization_id,employee_id)where status='open';create index attendance_daily_idx on public.attendance_sessions(organization_id,work_date,branch_id,status);create index attendance_employee_timesheet_idx on public.attendance_sessions(employee_id,work_date desc);create index attendance_late_idx on public.attendance_sessions(organization_id,work_date,branch_id)where is_late;create index attendance_events_session_idx on public.attendance_events(session_id,occurred_at);
create trigger set_updated_at before update on public.employees for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.attendance_sessions for each row execute function private.set_updated_at();

create function private.employees_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='employees');$$;
create function private.attendance_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='attendance');$$;
create function private.employee_config(requested_organization_id uuid)returns jsonb language sql stable security definer set search_path='' as $$select coalesce(module.config,'{}')from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='employees';$$;
create function private.attendance_config(requested_organization_id uuid)returns jsonb language sql stable security definer set search_path='' as $$select coalesce(module.config,'{}')from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='attendance';$$;
create function private.next_employee_number(requested_organization_id uuid)returns text language plpgsql security definer set search_path='' as $$declare value bigint;prefix text;begin insert into public.employee_counters(organization_id,next_value)values(requested_organization_id,2)on conflict(organization_id)do update set next_value=public.employee_counters.next_value+1 returning next_value-1 into value;if value is null then value:=1;end if;prefix:=upper(coalesce(nullif(btrim(private.employee_config(requested_organization_id)->>'employee_number_prefix'),''),'EMP'));return prefix||'-'||lpad(value::text,6,'0');end;$$;
create function private.can_read_attendance_session(requested_organization_id uuid,requested_session_id uuid)returns boolean language sql stable security definer set search_path='' as $$select private.attendance_module_enabled(requested_organization_id)and exists(select 1 from public.attendance_sessions session where session.id=requested_session_id and session.organization_id=requested_organization_id and private.can_business_permission(requested_organization_id,'attendance.read',session.branch_id));$$;

create function private.save_employee(requested_organization_id uuid,requested_employee_id uuid,requested_branch_id uuid,requested_name text,requested_contact text,requested_position text,requested_employment_status text,requested_hire_date date,requested_membership_id uuid)returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());target_id uuid:=coalesce(requested_employee_id,gen_random_uuid());record public.employees%rowtype;number text;begin
 if actor is null or not private.employees_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'employee.manage',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;
 if char_length(btrim(requested_name))not between 1 and 160 or char_length(coalesce(requested_contact,''))>500 or char_length(btrim(requested_position))not between 1 and 120 or requested_employment_status not in('active','on_leave','inactive','terminated')or requested_hire_date is null or requested_hire_date>current_date or not exists(select 1 from public.branches where id=requested_branch_id and organization_id=requested_organization_id and is_active)or(requested_membership_id is not null and not exists(select 1 from public.organization_memberships where id=requested_membership_id and organization_id=requested_organization_id and status='active'))then raise exception'Invalid employee.'using errcode='22023';end if;
 select*into record from public.employees where id=target_id and organization_id=requested_organization_id for update;if requested_employee_id is not null and record.id is null then raise exception'Employee not found.'using errcode='P0001';end if;if record.id is not null and not private.can_business_permission(requested_organization_id,'employee.manage',record.branch_id)then raise exception'Permission denied.'using errcode='42501';end if;
 if record.id is null then number:=private.next_employee_number(requested_organization_id);insert into public.employees(id,organization_id,branch_id,employee_number,name,contact,position,employment_status,hire_date,membership_id,created_by,updated_by)values(target_id,requested_organization_id,requested_branch_id,number,btrim(requested_name),btrim(coalesce(requested_contact,'')),btrim(requested_position),requested_employment_status,requested_hire_date,requested_membership_id,actor,actor);insert into public.employee_audit_history(organization_id,employee_id,event,actor_id,details)values(requested_organization_id,target_id,'created',actor,jsonb_build_object('employeeNumber',number));
 else update public.employees set branch_id=requested_branch_id,name=btrim(requested_name),contact=btrim(coalesce(requested_contact,'')),position=btrim(requested_position),employment_status=requested_employment_status,hire_date=requested_hire_date,membership_id=requested_membership_id,updated_by=actor where id=target_id;insert into public.employee_audit_history(organization_id,employee_id,event,actor_id,details)values(requested_organization_id,target_id,'updated',actor,jsonb_build_object('fromStatus',record.employment_status,'toStatus',requested_employment_status));end if;return target_id;
end;$$;

create function private.record_attendance_event(requested_organization_id uuid,requested_employee_id uuid,requested_branch_id uuid,requested_event_type text,requested_occurred_at timestamptz,requested_device_info jsonb,requested_latitude numeric,requested_longitude numeric,requested_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());employee public.employees%rowtype;session public.attendance_sessions%rowtype;last_event public.attendance_events%rowtype;target_session_id uuid;config jsonb;timezone_name text:='Asia/Manila';shift_start time;grace integer;standard_minutes integer;work_date_value date;local_time time;break_delta integer;worked integer;begin
 if actor is null or not private.attendance_module_enabled(requested_organization_id)or not private.employees_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'attendance.clock',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;
 if requested_event_type not in('clock_in','break_start','break_end','clock_out')or requested_occurred_at is null or requested_occurred_at>now()+interval'5 minutes'or jsonb_typeof(requested_device_info)<>'object'or octet_length(requested_device_info::text)>8192 or char_length(requested_idempotency_key)not between 1 and 200 or((requested_latitude is null)<>(requested_longitude is null))or requested_latitude not between -90 and 90 or requested_longitude not between -180 and 180 or not exists(select 1 from public.branches where id=requested_branch_id and organization_id=requested_organization_id and is_active)then raise exception'Invalid attendance event.'using errcode='22023';end if;
 select session_id into target_session_id from public.attendance_events where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if target_session_id is not null then return target_session_id;end if;
 perform pg_advisory_xact_lock(hashtextextended(requested_organization_id||':attendance:'||requested_employee_id,0));select*into employee from public.employees where id=requested_employee_id and organization_id=requested_organization_id;if employee.id is null or employee.employment_status<>'active'then raise exception'Employee is not active.'using errcode='P0001';end if;
 select*into session from public.attendance_sessions where organization_id=requested_organization_id and employee_id=requested_employee_id and status='open'for update;config:=private.attendance_config(requested_organization_id);if requested_latitude is not null and not coalesce((config->>'capture_location')::boolean,false)then raise exception'Location capture is disabled.'using errcode='P0001';end if;shift_start:=coalesce(nullif(config->>'shift_start','')::time,time'09:00');grace:=coalesce((config->>'grace_period_minutes')::integer,0);standard_minutes:=coalesce((config->>'standard_day_minutes')::integer,480);work_date_value:=(requested_occurred_at at time zone timezone_name)::date;local_time:=(requested_occurred_at at time zone timezone_name)::time;
 if requested_event_type='clock_in'then if session.id is not null then raise exception'Employee already has an open attendance session.'using errcode='P0001';end if;insert into public.attendance_sessions(organization_id,employee_id,branch_id,work_date,clock_in_at,is_late,created_by)values(requested_organization_id,employee.id,requested_branch_id,work_date_value,requested_occurred_at,local_time>shift_start+make_interval(mins=>grace),actor)returning id into target_session_id;
 else if session.id is null then raise exception'Employee has no open attendance session.'using errcode='P0001';end if;if requested_occurred_at<session.clock_in_at then raise exception'Attendance events must be chronological.'using errcode='P0001';end if;select*into last_event from public.attendance_events where session_id=session.id order by occurred_at desc,id desc limit 1;
  if requested_event_type='break_start'and last_event.event_type='break_start'then raise exception'Employee is already on break.'using errcode='P0001';elsif requested_event_type='break_end'and last_event.event_type<>'break_start'then raise exception'Employee is not on break.'using errcode='P0001';elsif requested_event_type='clock_out'and last_event.event_type='break_start'then raise exception'End the break before clocking out.'using errcode='P0001';end if;target_session_id:=session.id;
  if requested_event_type='break_end'then break_delta:=greatest(0,floor(extract(epoch from(requested_occurred_at-last_event.occurred_at))/60)::integer);update public.attendance_sessions set break_minutes=break_minutes+break_delta where id=session.id;elsif requested_event_type='clock_out'then worked:=greatest(0,floor(extract(epoch from(requested_occurred_at-session.clock_in_at))/60)::integer-session.break_minutes);update public.attendance_sessions set clock_out_at=requested_occurred_at,status='closed',worked_minutes=worked,regular_minutes=least(worked,standard_minutes),overtime_minutes=greatest(0,worked-standard_minutes),payroll_status='ready'where id=session.id;end if;
 end if;
 insert into public.attendance_events(organization_id,session_id,employee_id,branch_id,event_type,occurred_at,device_info,latitude,longitude,idempotency_key,created_by)values(requested_organization_id,target_session_id,employee.id,requested_branch_id,requested_event_type,requested_occurred_at,requested_device_info,requested_latitude,requested_longitude,requested_idempotency_key,actor);return target_session_id;
exception when invalid_text_representation or datetime_field_overflow then raise exception'Invalid attendance configuration or event.'using errcode='22023';end;$$;

create function public.save_employee(requested_organization_id uuid,requested_employee_id uuid,requested_branch_id uuid,requested_name text,requested_contact text,requested_position text,requested_employment_status text,requested_hire_date date,requested_membership_id uuid)returns uuid language sql security definer set search_path='' as $$select private.save_employee(requested_organization_id,requested_employee_id,requested_branch_id,requested_name,requested_contact,requested_position,requested_employment_status,requested_hire_date,requested_membership_id);$$;
create function public.record_attendance_event(requested_organization_id uuid,requested_employee_id uuid,requested_branch_id uuid,requested_event_type text,requested_occurred_at timestamptz,requested_device_info jsonb,requested_latitude numeric,requested_longitude numeric,requested_idempotency_key text)returns uuid language sql security definer set search_path='' as $$select private.record_attendance_event(requested_organization_id,requested_employee_id,requested_branch_id,requested_event_type,requested_occurred_at,requested_device_info,requested_latitude,requested_longitude,requested_idempotency_key);$$;

alter table public.employees enable row level security;alter table public.employee_audit_history enable row level security;alter table public.attendance_sessions enable row level security;alter table public.attendance_events enable row level security;
create policy employees_read on public.employees for select to authenticated using((select private.employees_module_enabled(organization_id))and private.can_business_permission(organization_id,'employee.read',branch_id));
create policy employee_audit_read on public.employee_audit_history for select to authenticated using(exists(select 1 from public.employees employee where employee.id=employee_audit_history.employee_id and employee.organization_id=employee_audit_history.organization_id and private.employees_module_enabled(employee_audit_history.organization_id)and private.can_business_permission(employee_audit_history.organization_id,'employee.read',employee.branch_id)));
create policy attendance_sessions_read on public.attendance_sessions for select to authenticated using((select private.attendance_module_enabled(organization_id))and private.can_business_permission(organization_id,'attendance.read',branch_id));
create policy attendance_events_read on public.attendance_events for select to authenticated using((select private.can_read_attendance_session(organization_id,session_id)));
revoke all on table public.employee_counters,public.employees,public.employee_audit_history,public.attendance_sessions,public.attendance_events from public,anon,authenticated;grant select on table public.employees,public.employee_audit_history,public.attendance_sessions,public.attendance_events to authenticated;
revoke all on function private.install_employee_attendance_permissions(uuid),private.handle_main_branch_employee_attendance_permissions(),private.employees_module_enabled(uuid),private.attendance_module_enabled(uuid),private.employee_config(uuid),private.attendance_config(uuid),private.next_employee_number(uuid),private.can_read_attendance_session(uuid,uuid),private.save_employee(uuid,uuid,uuid,text,text,text,text,date,uuid),private.record_attendance_event(uuid,uuid,uuid,text,timestamptz,jsonb,numeric,numeric,text)from public,anon,authenticated;
grant execute on function private.employees_module_enabled(uuid),private.attendance_module_enabled(uuid),private.can_read_attendance_session(uuid,uuid)to authenticated;
revoke all on function public.save_employee(uuid,uuid,uuid,text,text,text,text,date,uuid),public.record_attendance_event(uuid,uuid,uuid,text,timestamptz,jsonb,numeric,numeric,text)from public,anon;grant execute on function public.save_employee(uuid,uuid,uuid,text,text,text,text,date,uuid),public.record_attendance_event(uuid,uuid,uuid,text,timestamptz,jsonb,numeric,numeric,text)to authenticated;
comment on table public.attendance_events is'Immutable source events for attendance. Sessions are safely materialized summaries for dashboards and future payroll.';
comment on column public.attendance_sessions.payroll_status is'Integration boundary only; payroll calculation and export are intentionally not implemented.';
